#define UART_RBR 0x0u
#define UART_THR 0x0u
#define UART_IER 0x1u
#define UART_FCR 0x2u
#define UART_LSR 0x5u
#define UART_IER_RDA 0x01u
#define UART_LSR_DR 0x01u
#define UART_LSR_THRE 0x20u
#define UART_FCR_ENABLE 0x01u
#define UART_FCR_RX_RESET 0x02u
#define UART_FCR_TX_RESET 0x04u

static inline uint8_t uart_read_reg(uint32_t offset) {
    return *(volatile uint8_t *)(UART_BASE + offset);
}

static inline void uart_write_reg(uint32_t offset, uint8_t data) {
    *(volatile uint8_t *)(UART_BASE + offset) = data;
}

static void uart_rx_prepare_polling(void) {
    uart_write_reg(UART_IER, 0x00);
    // Do not reset TX here: the previous answer may still be draining from the
    // FIFO when the next prompt is armed.
    uart_write_reg(UART_FCR, UART_FCR_ENABLE | UART_FCR_RX_RESET);
}

static void uart_putc(char ch) {
    while ((uart_read_reg(UART_LSR) & UART_LSR_THRE) == 0) {
    }
    uart_write_reg(UART_THR, (uint8_t)ch);
}

static char uart_getc_blocking(void) {
    while ((uart_read_reg(UART_LSR) & UART_LSR_DR) == 0) {
    }
    return (char)uart_read_reg(UART_RBR);
}

static int uart_getc_nonblocking(char *ch) {
    if ((uart_read_reg(UART_LSR) & UART_LSR_DR) == 0) {
        return 0;
    }
    *ch = (char)uart_read_reg(UART_RBR);
    return 1;
}

void _exit(int code) {
    (void)code;
    while (1) {
        __asm__ __volatile__("idle 0" ::: "memory");
    }
}

int close(int fd) {
    (void)fd;
    return -1;
}

int fstat(int fd, void *st) {
    (void)fd;
    (void)st;
    return 0;
}

int isatty(int fd) {
    (void)fd;
    return 1;
}

off_t lseek(int fd, off_t offset, int whence) {
    (void)fd;
    (void)offset;
    (void)whence;
    return 0;
}

long long lseek64(int fd, long long offset, int whence) {
    (void)fd;
    (void)offset;
    (void)whence;
    return 0;
}

int read(int fd, void *buf, unsigned int count) {
    if (fd != 0 || buf == NULL || count == 0) {
        return -1;
    }

    char *p = (char *)buf;
    for (unsigned int n = 0; n < count; n++) {
        char ch = uart_getc_blocking();
        if (ch == '\r') {
            ch = '\n';
        }
        p[n] = ch;
        if (ch == '\n') {
            return (int)(n + 1);
        }
    }
    return (int)count;
}

int write(int fd, const void *buf, unsigned int count) {
    (void)fd;
    const char *p = (const char *)buf;
    for (unsigned int i = 0; i < count; i++) {
        uart_putc(p[i]);
    }
    return (int)count;
}

static inline void cpu_idle(void)
{
    __asm__ __volatile__("idle 0" ::: "memory");
}

static inline void cb_write(unsigned long offset, unsigned long value)
{
    RegWrite(CB_BASE + offset, value);
}

static inline unsigned long cb_read(unsigned long offset)
{
    return RegRead(CB_BASE + offset);
}

void HWI1_IntrHandler(void){
    cb_write(REG_CTRL_ADDR, 0);
}

// ----------------------------------------------------------------------------
// LACC/TPU interface

#define TPU_STATUS_BUSY  (1u << 0)
#define TPU_STATUS_DONE  (1u << 1)
#define TPU_STATUS_ERROR (1u << 2)

#define TPU_STATUS_RESULT_COUNT(status) (((status) >> 8) & 0xffu)
#define TPU_STATUS_ERROR_CODE(status)   (((status) >> 16) & 0xffu)

#define LACC_START_WORD     "0xC00000A4"
#define LACC_STATUS_WORD    "0xC0400004"
#define LACC_READ_WORD      "0xC08000A4"
#define LACC_UB_WRITE_WORD  "0xC08098A4"
#define LACC_SET_MODE_WORD  "0xC08100A4"
#define LACC_DMA_LOAD_WORD  "0xC08198A4"
#define LACC_CLEAR_WORD     "0xC0C00004"

#define TPU_TILE 8
#define TPU_K_CHUNK 64
#define TPU_BANK_STRIDE 1024
#define TPU_TILE_HALFWORDS (TPU_K_CHUNK + TPU_K_CHUNK * TPU_TILE)

static inline uint32_t tpu_start(uint32_t start_pc) {
    uint32_t status;
    asm volatile (
        "move $r5, %1\n\t"
        ".word " LACC_START_WORD "\n\t"
        "move %0, $r4\n\t"
        : "=r"(status)
        : "r"(start_pc)
        : "$r4", "$r5", "memory"
    );
    return status;
}

static inline uint32_t tpu_status(void) {
    uint32_t status;
    asm volatile (
        ".word " LACC_STATUS_WORD "\n\t"
        "move %0, $r4\n\t"
        : "=r"(status)
        :
        : "$r4", "memory"
    );
    return status;
}

static inline uint32_t tpu_read_pair(uint32_t pair_index) {
    uint32_t value;
    asm volatile (
        "move $r5, %1\n\t"
        ".word " LACC_READ_WORD "\n\t"
        "move %0, $r4\n\t"
        : "=r"(value)
        : "r"(pair_index)
        : "$r4", "$r5", "memory"
    );
    return value;
}

static inline uint32_t tpu_ub_write(uint32_t ub_addr, uint32_t data) {
    uint32_t status;
    asm volatile (
        "move $r5, %1\n\t"
        "move $r6, %2\n\t"
        ".word " LACC_UB_WRITE_WORD "\n\t"
        "move %0, $r4\n\t"
        : "=r"(status)
        : "r"(ub_addr), "r"(data)
        : "$r4", "$r5", "$r6", "memory"
    );
    return status;
}

static inline uint32_t tpu_set_raw_result_mode(uint32_t enable) {
    uint32_t status;
    asm volatile (
        "move $r5, %1\n\t"
        ".word " LACC_SET_MODE_WORD "\n\t"
        "move %0, $r4\n\t"
        : "=r"(status)
        : "r"(enable)
        : "$r4", "$r5", "memory"
    );
    return status;
}

static inline uint32_t tpu_dma_load(uint32_t descriptor_addr) {
    uint32_t status;
    asm volatile (
        "move $r5, %1\n\t"
        ".word " LACC_DMA_LOAD_WORD "\n\t"
        "move %0, $r4\n\t"
        : "=r"(status)
        : "r"(descriptor_addr)
        : "$r4", "$r5", "memory"
    );
    return status;
}

static inline uint32_t tpu_clear(void) {
    uint32_t value;
    asm volatile (
        ".word " LACC_CLEAR_WORD "\n\t"
        "move %0, $r4\n\t"
        : "=r"(value)
        :
        : "$r4", "memory"
    );
    return value;
}

static int tpu_wait_done(uint32_t min_result_count, uint32_t *status_out) {
    for (uint32_t i = 0; i < LLAMA_TPU_TIMEOUT; i++) {
        const uint32_t status = tpu_status();
        if (status & TPU_STATUS_ERROR) {
            *status_out = status;
            return -1;
        }
        if ((status & TPU_STATUS_DONE) &&
            TPU_STATUS_RESULT_COUNT(status) >= min_result_count) {
            *status_out = status;
            return 0;
        }
    }
    *status_out = tpu_status();
    return 1;
}

static int tpu_wait_idle(uint32_t *status_out) {
    for (uint32_t i = 0; i < LLAMA_TPU_TIMEOUT; i++) {
        const uint32_t status = tpu_status();
        if (status & TPU_STATUS_ERROR) {
            *status_out = status;
            return -1;
        }
        if ((status & TPU_STATUS_DONE) && !(status & TPU_STATUS_BUSY)) {
            *status_out = status;
            return 0;
        }
    }
    *status_out = tpu_status();
    return 1;
}

static int tpu_wait_cleared(uint32_t *status_out) {
    for (uint32_t i = 0; i < LLAMA_TPU_TIMEOUT; i++) {
        const uint32_t status = tpu_status();
        if (!(status & (TPU_STATUS_BUSY | TPU_STATUS_DONE | TPU_STATUS_ERROR))) {
            *status_out = status;
            return 0;
        }
    }
    *status_out = tpu_status();
    return 1;
}

static inline uint16_t float_bits_to_q8_8(uint32_t bits) {
    const uint32_t sign = bits >> 31;
    const uint32_t exponent = (bits >> 23) & 0xffu;

    if (exponent == 0) {
        return 0;
    }
    if (exponent == 0xffu) {
        return sign ? 0x8000u : 0x7fffu;
    }

    const uint32_t mantissa = (bits & 0x7fffffu) | 0x800000u;
    const int shift = (int)exponent - 142; // value * 256 = mantissa * 2^shift
    uint32_t magnitude;

    if (shift >= 0) {
        magnitude = 32768u;
    } else {
        const unsigned int right_shift = (unsigned int)(-shift);
        if (right_shift >= 32u) {
            magnitude = 0;
        } else {
            const uint32_t round = 1u << (right_shift - 1u);
            magnitude = (mantissa + round) >> right_shift;
        }
    }

    if (sign) {
        if (magnitude >= 32768u) return 0x8000u;
        return (uint16_t)(-(int32_t)magnitude);
    }
    if (magnitude > 32767u) return 0x7fffu;
    return (uint16_t)magnitude;
}

static inline uint16_t float_to_q8_8(float value) {
    uint32_t bits;
    memcpy(&bits, &value, sizeof(bits));
    return float_bits_to_q8_8(bits);
}

static inline float q8_8_to_float(uint16_t value) {
    return (float)(int16_t)value / 256.0f;
}

// Data Structures

typedef struct {
    int dim;        // transformer dimension
    int hidden_dim; // for FFN layers
    int n_layers;   // number of layers
    int n_heads;    // number of query heads
    int n_kv_heads; // number of key/value heads (can be < n_heads)
    int vocab_size; // vocabulary size
    int seq_len;    // max sequence length
} Config;

typedef struct {
    // token embedding table
    float* token_embedding_table;   // (vocab_size, dim)
    // weights for rmsnorms
    float* rms_att_weight;          // (layer, dim) rmsnorm weights
    float* rms_ffn_weight;          // (layer, dim)
    // weights for matmuls
    const int16_t* wq;              // Q8.8 (layer, dim, n_heads * head_size)
    const int16_t* wk;              // Q8.8 (layer, dim, n_kv_heads * head_size)
    const int16_t* wv;              // Q8.8 (layer, dim, n_kv_heads * head_size)
    const int16_t* wo;              // Q8.8 (layer, n_heads * head_size, dim)
    // weights for ffn
    const int16_t* w1;              // Q8.8 (layer, hidden_dim, dim)
    const int16_t* w2;              // Q8.8 (layer, dim, hidden_dim)
    const int16_t* w3;              // Q8.8 (layer, hidden_dim, dim)
    // final rmsnorm
    float* rms_final_weight;        // (dim,)
    // classifier weights
    const int16_t* wcls;            // Q8.8 classifier weights
} TransformerWeights;

typedef struct {
    // current wave of activations
    float *x;           // activation at current time stamp (dim,)
    float *xb;          // same, but inside a residual branch (dim,)
    float *xb2;         // an additional buffer for convenience (dim,)
    float *hb;          // buffer for hidden dimension in FFN (hidden_dim,)
    float *hb2;         // buffer for hidden dimension in FFN (hidden_dim,)
    float *q;           // query (dim,)
    float *k;           // key (kv_dim,)
    float *v;           // value (kv_dim,)
    float *att;         // buffer for scores/attention values (n_heads, seq_len)
    float *logits;      // output logits
    // kv cache
    float* key_cache;   // (layer, seq_len, kv_dim)
    float* value_cache; // (layer, seq_len, kv_dim)
} RunState;

typedef struct {
    Config config;
    // Keep the validated GQA width in memory. TPU custom instructions and the
    // long inlined matmul path must not be allowed to corrupt a caller-held
    // dimension and turn a K/V projection into an out-of-bounds matrix read.
    volatile int kv_dim;
    TransformerWeights weights;
    RunState state;
    // pointer to the embedded model data
    const float* data;
    size_t file_size;
} Transformer;

extern char _data_lma[];
extern char _data[];
extern char _edata[];
extern char __heap_start[];
extern char __heap_end[];
extern const int16_t runc_q8_weights[];
extern const int16_t runc_q8_weights_end[];

static const void *load_image_alias(const void *ptr) {
    uintptr_t addr = (uintptr_t)ptr;
    uintptr_t data_start = (uintptr_t)_data;
    uintptr_t data_end = (uintptr_t)_edata;
    if (addr >= data_start && addr < data_end) {
        return (const void *)((uintptr_t)_data_lma + (addr - data_start));
    }
    return ptr;
}

static int config_is_plausible(const Config *p) {
    int vocab = p->vocab_size < 0 ? -p->vocab_size : p->vocab_size;
    if (p->dim <= 0 || p->dim > 4096) return 0;
    if (p->hidden_dim <= 0 || p->hidden_dim > 16384) return 0;
    if (p->n_layers <= 0 || p->n_layers > 128) return 0;
    if (p->n_heads <= 0 || p->n_heads > 128) return 0;
    if (p->n_kv_heads <= 0 || p->n_kv_heads > p->n_heads) return 0;
    if (vocab <= 0 || vocab > 200000) return 0;
    if (p->seq_len <= 0 || p->seq_len > 8192) return 0;
    if ((p->dim % p->n_heads) != 0) return 0;
    return 1;
}

static const unsigned char *resolve_model_blob(void) {
    Config probe;
    const unsigned char *data = stories_bin;
    const unsigned char *alias = (const unsigned char *)load_image_alias(data);
    if (alias != data) {
        memcpy(&probe, alias, sizeof(probe));
        if (config_is_plausible(&probe)) {
            printf("[llama] using model load-image copy\n");
            return alias;
        }
    }

    memcpy(&probe, data, sizeof(probe));
    if (config_is_plausible(&probe)) {
        return data;
    }

    fprintf(stderr,
            "invalid model header (dim=%d hidden=%d layers=%d heads=%d kv=%d vocab=%d seq=%d)\n",
            probe.dim, probe.hidden_dim, probe.n_layers, probe.n_heads,
            probe.n_kv_heads, probe.vocab_size, probe.seq_len);
    exit(EXIT_FAILURE);
}

static int tokenizer_blob_is_plausible(const unsigned char *data, size_t len) {
    int max_token_length = 0;
    int first_len = 0;
    if (len < sizeof(int) + sizeof(float) + sizeof(int)) return 0;
    memcpy(&max_token_length, data, sizeof(int));
    if (max_token_length <= 0 || max_token_length > 1024) return 0;
    memcpy(&first_len, data + sizeof(int) + sizeof(float), sizeof(int));
    if (first_len <= 0 || first_len > max_token_length || first_len > 256) return 0;
    if (sizeof(int) + sizeof(float) + sizeof(int) + (size_t)first_len > len) return 0;
    return 1;
}

static const unsigned char *resolve_tokenizer_blob(void) {
    const unsigned char *data = tok512_bin;
    const unsigned char *alias = (const unsigned char *)load_image_alias(data);
    if (alias != data && tokenizer_blob_is_plausible(alias, tok512_bin_len)) {
        printf("[llama] using tokenizer load-image copy\n");
        return alias;
    }

    if (tokenizer_blob_is_plausible(data, tok512_bin_len)) {
        return data;
    }

    fprintf(stderr, "invalid tokenizer header\n");
    exit(EXIT_FAILURE);
}

// ----------------------------------------------------------------------------
// Memory allocation and management

void malloc_run_state(RunState* s, Config* p) {
    int kv_dim = (p->dim * p->n_kv_heads) / p->n_heads;
    size_t state_bytes = ((size_t)p->dim * 4u +
                          (size_t)p->hidden_dim * 2u +
                          (size_t)p->n_heads * p->seq_len +
                          (size_t)p->vocab_size +
                          (size_t)p->n_layers * p->seq_len * kv_dim * 2u) * sizeof(float);
    size_t heap_bytes = (size_t)(__heap_end - __heap_start);
    printf("[llama] allocating run state bytes=%u heap=%u...\n",
           (unsigned int)state_bytes, (unsigned int)heap_bytes);

    // Every buffer is fully written before it is read. In particular, attention
    // only visits cache positions <= pos, so clearing the complete KV cache here
    // wastes hundreds of thousands of CPU stores (and dominates RTL simulation).
    s->x = malloc((size_t)p->dim * sizeof(float));
    s->xb = malloc((size_t)p->dim * sizeof(float));
    s->xb2 = malloc((size_t)p->dim * sizeof(float));
    s->hb = malloc((size_t)p->hidden_dim * sizeof(float));
    s->hb2 = malloc((size_t)p->hidden_dim * sizeof(float));
    s->q = malloc((size_t)p->dim * sizeof(float));
    s->k = NULL;
    s->v = NULL;
    s->att = malloc((size_t)p->n_heads * p->seq_len * sizeof(float));
    s->logits = malloc((size_t)p->vocab_size * sizeof(float));
    s->key_cache = malloc((size_t)p->n_layers * p->seq_len * kv_dim * sizeof(float));
    s->value_cache = malloc((size_t)p->n_layers * p->seq_len * kv_dim * sizeof(float));
    // ensure all mallocs were successful
	    if (!s->x || !s->xb || !s->xb2 || !s->hb || !s->hb2 || !s->q
     || !s->att || !s->logits || !s->key_cache || !s->value_cache) {
        fprintf(stderr, "malloc failed in malloc_run_state (dim=%d hidden=%d layers=%d seq=%d vocab=%d)\n",
                p->dim, p->hidden_dim, p->n_layers, p->seq_len, p->vocab_size);
        exit(EXIT_FAILURE);
    }
    printf("[llama] run state ready\n");
}

void free_run_state(RunState* s) {
    free(s->x); free(s->xb); free(s->xb2); free(s->hb); free(s->hb2);
    free(s->q); free(s->att); free(s->logits);
    free(s->key_cache); free(s->value_cache);
}

void memory_map_weights(TransformerWeights *w, Config* p, float* ptr, int shared_weights) {
    int head_size = p->dim / p->n_heads;
    // make sure the multiplications below are done in 64bit to fit the parameter counts of 13B+ models
    unsigned long long n_layers = p->n_layers;
    size_t wq_count = (size_t)n_layers * p->dim * (p->n_heads * head_size);
    size_t wk_count = (size_t)n_layers * p->dim * (p->n_kv_heads * head_size);
    size_t wv_count = wk_count;
    size_t wo_count = (size_t)n_layers * (p->n_heads * head_size) * p->dim;
    size_t w1_count = (size_t)n_layers * p->dim * p->hidden_dim;
    size_t w2_count = (size_t)n_layers * p->hidden_dim * p->dim;
    size_t w3_count = w1_count;
    size_t wcls_count = (size_t)p->vocab_size * p->dim;
    const int16_t *qptr = runc_q8_weights;

    (void)shared_weights;
    w->token_embedding_table = ptr;
    ptr += p->vocab_size * p->dim;
    w->rms_att_weight = ptr;
    ptr += n_layers * p->dim;
    w->wq = qptr;
    qptr += wq_count;
    ptr += wq_count;
    w->wk = qptr;
    qptr += wk_count;
    ptr += wk_count;
    w->wv = qptr;
    qptr += wv_count;
    ptr += wv_count;
    w->wo = qptr;
    qptr += wo_count;
    ptr += wo_count;
    w->rms_ffn_weight = ptr;
    ptr += n_layers * p->dim;
    w->w1 = qptr;
    qptr += w1_count;
    ptr += w1_count;
    w->w2 = qptr;
    qptr += w2_count;
    ptr += w2_count;
    w->w3 = qptr;
    qptr += w3_count;
    ptr += w3_count;
    w->rms_final_weight = ptr;
    w->wcls = qptr;
    qptr += wcls_count;

    if (qptr != runc_q8_weights_end) {
        fprintf(stderr, "packed TPU weight size mismatch\n");
        exit(EXIT_FAILURE);
    }
    printf("[llama] using build-time TPU Q8.8 weights\n");
}

// CORRECTED: The order of operations in this function is now correct.
void build_transformer(Transformer *t) {
    // MODIFICATION: Instead of opening a file, point directly to the embedded data array.
    t->data = (const float*)resolve_model_blob();
    t->file_size = stories_bin_len;

    // Read the header metadata from the beginning of the data block
    const float* data_ptr = t->data;

    // --- FIX START ---
    // 1. First, copy the config from the data blob into the transformer struct.
    memcpy(&t->config, data_ptr, sizeof(Config));

    // 2. Now that t->config is populated, we can use its values.
    // The negative vocab_size is a hacky way of signaling unshared weights.
    int shared_weights = t->config.vocab_size > 0 ? 1 : 0;
    t->config.vocab_size = abs(t->config.vocab_size);
    t->kv_dim = (t->config.dim / t->config.n_heads) * t->config.n_kv_heads;
    printf("[llama] model dim=%d hidden=%d layers=%d heads=%d kv_heads=%d kv_dim=%d vocab=%d seq=%d\n",
           t->config.dim,
           t->config.hidden_dim,
           t->config.n_layers,
           t->config.n_heads,
           t->config.n_kv_heads,
           t->kv_dim,
           t->config.vocab_size,
           t->config.seq_len);
    
    // 3. The weights start right after the config header.
    float* weights_ptr = (float*)(data_ptr + (sizeof(Config) / sizeof(float)));
    memory_map_weights(&t->weights, &t->config, weights_ptr, shared_weights);
    // --- FIX END ---

    // Allocate memory for the run state
    malloc_run_state(&t->state, &t->config);
}

void free_transformer(Transformer* t) {
    // MODIFICATION: Do NOT free t->data, as it points to a static array
    // in the executable's data segment, not heap-allocated memory.
    // if (t->data != NULL) {
    //     free(t->data);
    // }
    
    // Free the run state buffers
    free_run_state(&t->state);
}


// ----------------------------------------------------------------------------
// Neural net layers

void rmsnorm(float* o, float* x, float* weight, int size) {
    // calculate sum of squares
    float ss = 0.0f;
    for (int j = 0; j < size; j++) {
        ss += x[j] * x[j];
    }
    ss /= size;
    ss += 1e-5f;
    ss = 1.0f / sqrtf(ss);
    // normalize and scale
    for (int j = 0; j < size; j++) {
        o[j] = weight[j] * (ss * x[j]);
    }
}

void softmax(float* x, int size) {
    if (size == 1) { x[0] = 1.0f; return; }
    // find max value (for numerical stability)
    float max_val = x[0];
    for (int i = 1; i < size; i++) {
        if (x[i] > max_val) {
            max_val = x[i];
        }
    }
    // exp and sum
    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        x[i] = expf(x[i] - max_val);
        sum += x[i];
    }
    // normalize
    for (int i = 0; i < size; i++) {
        x[i] /= sum;
    }
}

